using System.Collections;
using System.Collections.Generic;
using FMODUnity;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AstreaFirstPhaseSplittingHandler", menuName = "Data/Battle/AstreaFirstPhaseSplittingHandler", order = 0)]
public class AstreaFirstPhaseSplittingHandler : ScriptableObject
{
	[Header("Events")]
	[SerializeField]
	private FloatFloatEvent OnScreenShake;

	[SerializeField]
	private VoidEvent OnPlayBattleBGM;

	[Header("Second Phase Animation")]
	[SerializeField]
	private float firstShakeDuration;

	[SerializeField]
	private float firstShakePower;

	[SerializeField]
	private float astreaSplittingDuration;

	[SerializeField]
	private AnimationCurve astreaSplittingCurve;

	[SerializeField]
	private float secondShakeDuration;

	[SerializeField]
	private float secondShakePower;

	[SerializeField]
	private float screenShakeDuration;

	[SerializeField]
	private float screenShakePower;

	[SerializeField]
	private float delayToStartSFX = 0.6f;

	[SerializeField]
	private float delayToFirstScreenShakeAndVFX = 0.8f;

	[SerializeField]
	private float delayToFirstShake = 0.8f;

	[SerializeField]
	private float delayToInitializeBattle = 3f;

	[Header("VFX")]
	[SerializeField]
	private GameObject astreaChargingVFX;

	[SerializeField]
	private GameObject astreaBurstingVFX;

	[Header("Assets")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private BattleCorruptedAnimals currentBattleCorruptedAnimals;

	[SerializeField]
	private SaveSystem saveSystem;

	[Header("SFX")]
	[SerializeField]
	private EventReference astreaFirstPhaseStartOfBattleSFX;

	public IEnumerator AstreaSplittingAnimation()
	{
		Debug.Log("AstreaSplittingAnimation Started");
		List<GameObject> activeCorruptedAnimals = currentCorruptedAnimals.activeCorruptedAnimals;
		SpriteControl centerAstreaSpriteControl = activeCorruptedAnimals[1].GetComponent<SpriteControl>();
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToStartSFX, delegate
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(astreaFirstPhaseStartOfBattleSFX);
		});
		yield return new WaitForSeconds(delayToFirstScreenShakeAndVFX);
		Debug.Log("AstreaSplittingAnimation Screenshake");
		bool screenShakeEnabled = saveSystem.LoadScreenShake();
		OnScreenShake.Raise(screenShakePower, screenShakeDuration);
		bool vfxEnabled = ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled();
		if (vfxEnabled)
		{
			GameObject gameObject = Object.Instantiate(astreaBurstingVFX);
			gameObject.transform.position = centerAstreaSpriteControl.transform.position;
			Object.Destroy(gameObject, 5f);
		}
		if (screenShakeEnabled || vfxEnabled)
		{
			yield return new WaitForSeconds(delayToFirstShake);
		}
		Debug.Log("AstreaSplittingAnimation delayToFirstShake");
		Transform animationSkeletonTransform = centerAstreaSpriteControl.AnimationSkeletonTransform;
		CoroutineUtility.ShakeRoutine(ReferenceSingleton<CoroutineHandler>.Instance, animationSkeletonTransform, firstShakeDuration, firstShakePower);
		if (vfxEnabled)
		{
			GameObject gameObject2 = Object.Instantiate(astreaChargingVFX);
			gameObject2.transform.position = centerAstreaSpriteControl.transform.position;
			Object.Destroy(gameObject2, 5f);
		}
		yield return new WaitForSeconds(firstShakeDuration);
		Debug.Log("AstreaSplittingAnimation firstShakeDuration");
		CorruptedAnimalInitializer component = activeCorruptedAnimals.First().GetComponent<CorruptedAnimalInitializer>();
		component.CorruptedAnimalSpriteControlInitialize(currentBattleCorruptedAnimals.CorruptedAnimals.First());
		CorruptedAnimalInitializer component2 = activeCorruptedAnimals.Last().GetComponent<CorruptedAnimalInitializer>();
		component2.CorruptedAnimalSpriteControlInitialize(currentBattleCorruptedAnimals.CorruptedAnimals.Last());
		Transform skeletonTransform2 = centerAstreaSpriteControl.SkeletonTransform;
		component.GetComponent<SpriteControl>().SkeletonTransform.position = skeletonTransform2.position;
		component2.GetComponent<SpriteControl>().SkeletonTransform.position = skeletonTransform2.position;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (i != 1)
			{
				Vector3 finalPosition = activeCorruptedAnimals[i].transform.position;
				Transform skeletonTransform = activeCorruptedAnimals[i].GetComponent<SpriteControl>().SkeletonTransform;
				Vector3 startPosition = skeletonTransform.transform.position;
				ReferenceSingleton<CoroutineHandler>.Instance.Run(CoroutineUtility.CurveRoutine(astreaSplittingDuration, astreaSplittingCurve, delegate(float t, float v)
				{
					skeletonTransform.transform.position = Vector3.Lerp(startPosition, finalPosition, v);
				}));
			}
		}
		yield return new WaitForSeconds(astreaSplittingDuration);
		Debug.Log("AstreaSplittingAnimation astreaSplittingDuration");
		for (int j = 0; j < activeCorruptedAnimals.Count; j++)
		{
			Transform animationSkeletonTransform2 = activeCorruptedAnimals[j].GetComponent<SpriteControl>().AnimationSkeletonTransform;
			CoroutineUtility.ShakeRoutine(ReferenceSingleton<CoroutineHandler>.Instance, animationSkeletonTransform2, secondShakeDuration, secondShakePower);
		}
		yield return new WaitForSeconds(secondShakeDuration);
		Debug.Log("AstreaSplittingAnimation secondShakeDuration");
		for (int k = 0; k < activeCorruptedAnimals.Count; k++)
		{
			if (vfxEnabled)
			{
				GameObject gameObject3 = Object.Instantiate(astreaBurstingVFX);
				gameObject3.transform.position = activeCorruptedAnimals[k].transform.position;
				Object.Destroy(gameObject3, 5f);
			}
		}
		OnScreenShake.Raise(screenShakePower, screenShakeDuration);
		if (screenShakeEnabled || vfxEnabled)
		{
			yield return new WaitForSeconds(delayToInitializeBattle);
		}
		Debug.Log("AstreaSplittingAnimation delayToInitializeBattle");
		for (int l = 0; l < activeCorruptedAnimals.Count; l++)
		{
			activeCorruptedAnimals[l].SetActive(value: true);
			if (l != 1)
			{
				activeCorruptedAnimals[l].GetComponent<CorruptedAnimalInitializer>().Initialize(currentBattleCorruptedAnimals.CorruptedAnimals[l], startBattleInitialize: true, dontInitializeSpriteControl: true);
			}
		}
		ReferenceSingleton<GameStateManager>.Instance.InitializeBattle();
		OnPlayBattleBGM.Raise();
	}
}
